def save_result(pid,result):
    raw=result if isinstance(result,str) else json.dumps(result,ensure_ascii=False)
    (reviewdir/f'{pid}.raw.txt').write_text(raw)
    rec=records[pid]
    rec['raw_output_path']=str(reviewdir/f'{pid}.raw.txt')
    rec['output_sha256']=hashlib.sha256(raw.encode()).hexdigest()
    text=raw.strip()
    if text.startswith('```'):
        text=text.split('\n',1)[1].rsplit('```',1)[0].strip()
    try:
        data=json.loads(text)
        (reviewdir/f'{pid}.json').write_text(json.dumps(data,indent=2,ensure_ascii=False))
        rec['review_path']=str(reviewdir/f'{pid}.json')
        rec['fully_reviewed']=data.get('fully_reviewed')
        rec['status']='success' if data.get('fully_reviewed') is True and data.get('packet_id')==pid else 'incomplete'
        rec['finding_count']=len(data.get('findings',[]))
    except Exception as e:
        rec['status']='parse_error'; rec['error']=str(e)
    (reviewdir/f'{pid}.receipt.json').write_text(json.dumps(rec,indent=2))
    return {k:rec[k] for k in ('packet_id','status','finding_count') if k in rec}
for pid in ids[:3]:
    try: print(save_result(pid,handles[pid].wait()))
    except Exception as e:
        records[pid].update(status='completion_error',error=str(e)); print(pid,str(e))

